#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Deploy Chốt: web → Vercel (chot.nashng.dev), API → Railway (api.chot.nashng.dev), DNS ở Porkbun.
# Script CHỈ in hướng dẫn, chờ Enter và kiểm tra bằng curl/nslookup — không gọi API của dịch vụ
# nào, không ghi .env hay GitHub secret. Chạy trong Git Bash: bash scripts/deploy_wizard.sh

WEB_HOST="chot.nashng.dev"
API_HOST="api.chot.nashng.dev"

# http_code URL [curl args…] in ra mã HTTP (000 nếu không kết nối được).
http_code() { curl -s -o /dev/null -m 15 -w '%{http_code}' "$@" || true; }

# check "mô tả" lệnh… in ✓/✗ theo kết quả lệnh; trả về mã của lệnh.
check() {
  local label="$1"; shift
  if "$@"; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$label"; return 0; fi
  printf '  %s✗%s %s\n' "$RED" "$RESET" "$label"; return 1
}

# retry_until "mô tả" lệnh… lặp kiểm tra tới khi đạt hoặc người dùng bỏ qua.
retry_until() {
  local label="$1"; shift
  until check "$label" "$@"; do
    confirm "Chưa đạt. Thử lại? (n = bỏ qua, ghi vào việc còn lại)" || { SKIPPED+=("$label"); return 0; }
  done
}

health_ok() { [[ "$(http_code "https://$1/health")" == "200" ]]; }
# Biến Railway đã vào container? LEDGER_BUILDER=llm → builder "rules-v1|rules-v1".
llm_mode() { curl -s -m 15 "https://$1/health" | grep -q '"builder":"rules-v1|rules-v1"'; }
page_ok()   { [[ "$(http_code "https://$1")" =~ ^(200|307|308)$ ]]; }
cname_ok()  { nslookup "$1" 1.1.1.1 2>/dev/null | grep -qi "${2%.}"; }
cors_allows() {
  curl -s -m 15 -o /dev/null -D - -X OPTIONS "https://$API_HOST/meetings" \
    -H "Origin: $1" -H "Access-Control-Request-Method: POST" \
    -H "Access-Control-Request-Headers: content-type" | grep -qi "^access-control-allow-origin"
}
cors_blocks() { ! cors_allows "$1"; }
list_hidden() { [[ "$(http_code "https://$API_HOST/meetings")" =~ ^(404|405)$ ]]; }
env_untracked() { ! git ls-files --error-unmatch .env >/dev/null 2>&1; }
remote_up_to_date() { [[ "$(git rev-list --count '@{u}..HEAD' 2>/dev/null)" == "0" ]]; }

TOTAL_STAGES=8

banner "Deploy Chốt → $WEB_HOST + $API_HOST"

# ── 1. GitHub ──────────────────────────────────────────────────────────────
stage "GitHub: đẩy code lên trước"
say "Railway và Vercel build từ GitHub, nên code mới phải có trên remote."
check ".env KHÔNG bị git theo dõi" env_untracked \
  || { warn "Dừng lại: gỡ .env khỏi git (git rm --cached .env) rồi chạy lại."; exit 1; }
ahead=$(git rev-list --count '@{u}..HEAD' 2>/dev/null || echo "?")
note "Nhánh $(git branch --show-current) đang đi trước remote: $ahead commit."
if [[ "$ahead" != "0" ]]; then
  step "Tự chạy trong terminal khác:  git push"
  note "Thay đổi chưa commit (nếu có) sẽ KHÔNG được deploy — xem: git status --short"
  pause "Push xong thì Enter…"
  retry_until "Remote đã có mọi commit" remote_up_to_date
fi
pause "Enter để sang Railway…"

# ── 2. Railway: service + biến môi trường ──────────────────────────────────
stage "Railway: tạo service API"
open_url "https://railway.com/new"
step "New Project → Deploy from GitHub repo → chọn repo Chot_ai."
step "Mở service vừa tạo → Settings → Source → Root Directory: apps/api (Railway tự dùng Dockerfile)."
step "Tab Variables → Raw Editor → dán (điền key thật vào LLM_API_KEY):"
note "Khối dưới KHÔNG thụt đầu dòng — dán nguyên văn; dấu cách đầu dòng sẽ thành tên biến sai."
cat <<VARS

LEDGER_BUILDER=llm
REPLAY_EVENTS_DIR=demo_events
LLM_API_KEY=<key OpenAI, viết liền sau dấu =>
LLM_MODEL=gpt-4.1-mini
MAX_TRANSCRIPT_CHARS=20000
LLM_RATE_LIMIT_PER_HOUR=10
LLM_GLOBAL_LIMIT_PER_HOUR=60
PUBLIC_DEMO=true
CORS_ORIGINS=https://$WEB_HOST

VARS
step "Bấm Update Variables, rồi Deploy ở thanh trên cùng (biến chỉ có tác dụng sau khi deploy)."
note "Không cần đặt PORT — Railway tự cấp, Dockerfile đã đọc \$PORT."
step "Bấm Deploy, đợi tab Deployments báo thành công (log có 'Uvicorn running on')."
pause "Deploy xanh thì Enter…"

# ── 3. Railway: domain ─────────────────────────────────────────────────────
stage "Railway: domain tạm + custom domain"
step "Settings → Networking → Generate Domain (nếu hỏi Target port: lấy cổng ở dòng 'Uvicorn running on' trong log)."
ask RAILWAY_DOMAIN "Dán domain Railway vừa tạo (vd. chot-api-production.up.railway.app, không có https://):"
RAILWAY_DOMAIN="${RAILWAY_DOMAIN#https://}"; RAILWAY_DOMAIN="${RAILWAY_DOMAIN%/}"
retry_until "https://$RAILWAY_DOMAIN/health trả 200" health_ok "$RAILWAY_DOMAIN"
retry_until "API chạy chế độ LLM (biến Variables đã có tác dụng)" llm_mode "$RAILWAY_DOMAIN"
step "Vẫn ở Networking → Custom Domain → nhập: $API_HOST"
step "Railway hiện bản ghi DNS cần thêm: copy giá trị CNAME (và TXT nếu có)."
ask RAILWAY_CNAME "Dán giá trị CNAME Railway đưa (vd. xxxx.up.railway.app):"
ask RAILWAY_TXT "Railway có yêu cầu bản ghi TXT không? Dán 'host giá-trị', không có thì Enter:"
pause "Enter để sang Vercel…"

# ── 4. Vercel: project ─────────────────────────────────────────────────────
stage "Vercel: tạo project web"
open_url "https://vercel.com/new"
step "Add New → Project → Import repo Chot_ai."
step "Root Directory: apps/web (Framework tự nhận Next.js)."
step "Environment Variables: NEXT_PUBLIC_API_URL = https://$API_HOST"
note "Biến này nhúng lúc build — sửa sau thì phải Redeploy."
step "Bấm Deploy, đợi xong."
ask VERCEL_URL "Dán domain *.vercel.app của project (không có https://):"
VERCEL_URL="${VERCEL_URL#https://}"; VERCEL_URL="${VERCEL_URL%/}"
retry_until "https://$VERCEL_URL mở được" page_ok "$VERCEL_URL"
pause "Enter để thêm domain…"

# ── 5. Vercel: domain ──────────────────────────────────────────────────────
stage "Vercel: thêm $WEB_HOST"
step "Project → Settings → Domains → Add → nhập: $WEB_HOST"
step "Vercel hiện bản ghi cần thêm: copy giá trị CNAME (và TXT nếu có)."
ask VERCEL_CNAME "Dán giá trị CNAME Vercel đưa (vd. cname.vercel-dns.com):"
ask VERCEL_TXT "Vercel có yêu cầu bản ghi TXT không? Dán 'host giá-trị', không có thì Enter:"
pause "Enter để sang Porkbun…"

# ── 6. Porkbun DNS ─────────────────────────────────────────────────────────
stage "Porkbun: thêm bản ghi DNS"
open_url "https://porkbun.com/account/domainsSpeedy"
step "Domain Management → nashng.dev → DNS."
step "Thêm từng bản ghi dưới đây (Type / Host / Answer / TTL). KHÔNG sửa/xoá bản ghi cũ."
printf '\n  %-6s %-10s %-45s %s\n' "Type" "Host" "Answer" "TTL"
printf '  %-6s %-10s %-45s %s\n' "CNAME" "chot" "$VERCEL_CNAME" "600"
printf '  %-6s %-10s %-45s %s\n' "CNAME" "api.chot" "$RAILWAY_CNAME" "600"
if [[ -n "$RAILWAY_TXT" ]]; then printf '  %-6s %s (Railway)\n' "TXT" "$RAILWAY_TXT"; fi
if [[ -n "$VERCEL_TXT" ]]; then printf '  %-6s %s (Vercel)\n' "TXT" "$VERCEL_TXT"; fi
printf '\n'
note "Porkbun tự nối .nashng.dev vào Host — chỉ nhập 'chot' và 'api.chot'."
pause "Thêm xong thì Enter…"

# ── 7. Kiểm tra DNS, SSL, CORS ─────────────────────────────────────────────
stage "Kiểm tra (DNS + SSL mất 5–30 phút)"
retry_until "DNS $WEB_HOST → $VERCEL_CNAME" cname_ok "$WEB_HOST" "$VERCEL_CNAME"
retry_until "DNS $API_HOST → $RAILWAY_CNAME" cname_ok "$API_HOST" "$RAILWAY_CNAME"
note "Nếu Railway/Vercel còn báo 'Waiting for DNS / Pending', đợi SSL được cấp rồi thử lại."
retry_until "https://$API_HOST/health trả 200" health_ok "$API_HOST"
retry_until "API chạy chế độ LLM" llm_mode "$API_HOST"
retry_until "https://$WEB_HOST mở được" page_ok "$WEB_HOST"
retry_until "CORS cho phép https://$WEB_HOST" cors_allows "https://$WEB_HOST"
retry_until "CORS chặn origin lạ (https://evil.example)" cors_blocks "https://evil.example"
retry_until "GET /meetings bị ẩn (PUBLIC_DEMO=true)" list_hidden
pause "Enter để thử bằng tay…"

# ── 8. Thử bằng tay + chi phí ──────────────────────────────────────────────
stage "Thử thật trên trình duyệt"
open_url "https://$WEB_HOST"
step "Mở bằng cửa sổ ẩn danh: chọn mẫu m01 → Chốt biên bản → kết quả hiện ngay (replay, 0 token)."
step "Dán 1 transcript mới (vd. _claude/t01.txt) → Chốt → 10–30 giây (gọi LLM thật)."
step "Mục 'Cuộc họp gần đây' KHÔNG được hiện (PUBLIC_DEMO)."
confirm "Cả 3 đều đúng?" || SKIPPED+=("Thử tay trên https://$WEB_HOST chưa đạt — xem log Deploy ở Railway")
say ""
warn "Chi phí: Vercel Hobby miễn phí; Railway hết trial cần gói Hobby (https://railway.com/pricing)."
warn "Đặt budget tháng ở OpenAI → Settings → Limits để chặn chi phí LLM."
pause "Enter để kết thúc…"

finish
